# ❌ NAIVE SETUP: High exfiltration risk
naive_sandbox = {
    "filesystem": {
        "allowWrite": ["/home/user/"]
    },
    "network": {
        "allowedDomains": ["*.github.com"]
    }
}

# ✅ SECURE SETUP: Independently scoped axes
secure_sandbox = {
    "filesystem": {
        "allowWrite": ["/app/workspace/build"]
    },
    "network": {
        "allowedDomains": ["registry.npmjs.org"]
    }
}
